          Step 1: Account
        </span>
        {" → "}
        <span style={{ fontWeight: step === 2 ? "bold" : "normal" }}>
          Step 2: Profile
        </span>
        {" → "}
        <span style={{ fontWeight: step === 3 ? "bold" : "normal" }}>
          Step 3: Review
        </span>
      </div>

      {/* --- Step 1: Account Details --- */}
      {step === 1 && (
        <Form action={step1Action}>
